let squadOverviewOpener=null,squadOverviewSelectedIdentity=null;
function squadOverviewPreviewMarkup(m){
 const row=m.rows.find(p=>p.identity===squadOverviewSelectedIdentity)||m.rows[0];if(!row)return '';squadOverviewSelectedIdentity=row.identity;const p=season.squad[row.slot],esc=escapeText;
 return '<div class="squad-preview-body"><header>'+Portraits.html(p)+'<div><strong>'+esc(row.name)+'</strong><small>'+esc(row.positions.join(' / '))+'</small></div></header><div class="squad-preview-overall">종합 <b>'+row.overall+'</b><span>'+(row.starting?'선발':'후보')+'</span></div><dl>'+[['attack','공격'],['defense','수비'],['passing','패스'],['speed','속도'],['endurance','지구력'],['keeping','선방']].map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+p[key]+'</dd><meter min="0" max="100" value="'+p[key]+'" aria-label="'+label+' '+p[key]+'"></meter></div>').join('')+'</dl><p>체력 <b>'+row.energy+'</b> · '+esc(row.status||row.condition.label)+'</p><small>능력은 등록 포지션 기준 평가입니다. 전술 배치에 따른 평가는 전술 센터에서 확인하세요.</small></div><button type="button" id="squad-overview-detail" class="secondary">선수 상세 보고서</button>';
}
function selectSquadOverview(identity){
 squadOverviewSelectedIdentity=identity;const m=SquadOverview.read(season);$('squad-overview-preview').innerHTML=squadOverviewPreviewMarkup(m);$('squad-overview-detail').onclick=()=>openPlayerDetails(squadOverviewSelectedIdentity,$('squad-overview-detail'));$('squad-overview-dialog').querySelectorAll('[data-squad-detail]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.squadDetail===squadOverviewSelectedIdentity)));
}

function squadOverviewMarkup(m){
 const esc=escapeText;if(!m.rows.some(p=>p.identity===squadOverviewSelectedIdentity))squadOverviewSelectedIdentity=m.rows[0]?.identity;
 const rows=starting=>m.rows.filter(p=>p.starting===starting).map(p=>'<button type="button" class="squad-overview-row" data-squad-detail="'+esc(p.identity)+'" aria-pressed="'+(p.identity===squadOverviewSelectedIdentity)+'" aria-label="'+esc(p.name+' · 종합 '+p.overall+' · 체력 '+p.energy+' · '+(p.status||p.condition.label)+' · 미리보기')+'">'+Portraits.html(season.squad[p.slot])+'<span class="squad-overview-name"><strong>'+esc(p.name)+'</strong><small>#'+p.no+' · '+p.positions.join(' / ')+(p.status?' · '+p.status:'')+'</small></span><b>'+p.overall+'</b><span class="squad-overview-energy">'+p.energy+'<i aria-hidden="true"><em style="width:'+p.energy+'%"></em></i></span><span class="form-'+p.condition.tier+'">'+esc(p.condition.label)+'</span></button>').join('');
 return '<header><div><span class="eyebrow">우리 선수단</span><h2 id="squad-overview-title">우리 팀 전체 선수단</h2><small class="squad-overview-key">명단 숫자: 종합 · 체력 · 컨디션</small></div><button type="button" id="squad-overview-close" class="secondary" aria-label="선수단 명단 닫기">닫기 ×</button></header><div class="squad-overview-summary"><div><small>전체 평균 종합</small><strong>'+m.overall+'</strong></div><div><small>선발 평균 종합</small><strong>'+m.startingOverall+'</strong></div><div><small>출전 가능</small><strong>'+m.available+'<small> / '+m.total+'</small></strong></div></div><p class="squad-overview-composition">'+m.composition.map(p=>p.pos+' '+p.count+'명').join(' · ')+'</p><div class="squad-overview-columns" aria-hidden="true"><span>선수 · 포지션</span><span>종합</span><span>체력</span><span>컨디션</span></div><div class="squad-overview-list">'+[true,false].map(starting=>'<section aria-label="'+(starting?'선발':'후보')+'"><h3>'+(starting?'선발 명단':'후보 선수')+' <small>'+m.rows.filter(p=>p.starting===starting).length+'명</small></h3>'+rows(starting)+'</section>').join('')+'</div><aside id="squad-overview-preview" aria-label="선택한 선수 미리보기">'+squadOverviewPreviewMarkup(m)+'</aside><footer><p>종합: 주 포지션 능력의 가중 평균 · 컨디션: 코치 분석. 선수를 선택하고 상세 보고서 버튼으로 전체 능력을 확인하세요.</p><button type="button" id="squad-overview-plan" class="secondary">선발·교체 계획 보기</button></footer>';
}
function openSquadOverview(opener=document.activeElement){
 pauseForPlanning();squadOverviewOpener=opener;const dialog=$('squad-overview-dialog');dialog.innerHTML=squadOverviewMarkup(SquadOverview.read(season));
 $('squad-overview-detail').onclick=()=>openPlayerDetails(squadOverviewSelectedIdentity,$('squad-overview-detail'));
 $('squad-overview-close').onclick=()=>dialog.close();$('squad-overview-plan').onclick=()=>{dialog.close();if(managerGuideActive)return;setView('match');openMatchPopup('roster',$('primary'));};
 dialog.querySelectorAll('[data-squad-detail]').forEach(button=>button.onclick=()=>selectSquadOverview(button.dataset.squadDetail));
 if(!dialog.open)dialog.showModal();$('squad-overview-close').focus({preventScroll:true});
}
const squadOverviewDialog=document.createElement('dialog');squadOverviewDialog.id='squad-overview-dialog';squadOverviewDialog.setAttribute('aria-labelledby','squad-overview-title');document.body.append(squadOverviewDialog);
squadOverviewDialog.addEventListener('close',()=>squadOverviewOpener?.focus?.({preventScroll:true}));
